INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Hoodie Outrun','outrun-hoodie','La cavale a son uniforme. Ce hoodie molleton épais affiche à l''avant le motif Outrun et, au dos, la grille néon en perspective de la collection GETAWAY SEASON de ViceHub X — cette fenêtre électrique entre le dernier coup et l''autoroute. Rose, cyan, violet et orange s''allument sur le noir, phares chrome en accent. Molleton dense, capuche généreuse, cordon solide : le confort road-trip qui parle…','apparel',62.90,'EUR','stripe','GETAWAY SEASON',0,138,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='outrun-hoodie');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Tee Chrome Boulevard','chrome-boulevard-tee','Le boulevard s''allume, le chrome ruisselle. Ce tee coton 180g coupe classique porte à l''avant le motif Getaway et, au dos, le Chrome Boulevard néon de la collection GETAWAY SEASON de ViceHub X. Rose, cyan, violet et orange se reflètent sur le bitume mouillé du noir profond, phares chrome en signature. Une pièce sportswear-nostalgique légère, parfaite du café matinal à la virée nocturne, pensée…','apparel',33.90,'EUR','stripe','GETAWAY SEASON',0,139,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='chrome-boulevard-tee');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Zip Hoodie Getaway','getaway-zip-hoodie','Zippe, démarre, disparais. Ce zip hoodie premium noir affiche à l''avant le motif signature et, au dos, le Chrome Boulevard néon de la collection GETAWAY SEASON de ViceHub X. Rose, cyan, violet et orange glissent sur le noir profond comme des phares sur bitume mouillé. Molleton dense, zip robuste, capuche doublée : la couche polyvalente du road-trip, aussi juste sur la grille outrun qu''en ville…','apparel',72.90,'EUR','stripe','GETAWAY SEASON',0,140,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='getaway-zip-hoodie');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Gilet Puffer Getaway','getaway-puffer-vest','La chaleur de la cavale, sans les manches. Ce gilet puffer noir porte une broderie poitrine néon de la collection GETAWAY SEASON de ViceHub X — le clin d''œil discret d''initié entre le dernier coup et l''autoroute. Matelassage isolant, coupe streetwear, broderie rose et cyan qui claque sur le noir mat : la couche technique qui se superpose aussi bien sur hoodie que sous veste. Confectionné à la…','apparel',74.90,'EUR','stripe','GETAWAY SEASON',0,141,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='getaway-puffer-vest');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Sweat Col Rond Cassette Coast','cassette-coast-crewneck','Glisse la cassette, la côte défile. Ce sweat col rond heavyweight noir affiche à l''avant le motif Cassette Coast et, au dos, le Chrome Boulevard néon de la collection GETAWAY SEASON de ViceHub X — la bande-son du voyage entre deux villes. Rose, cyan, violet et orange s''illuminent sur le noir profond, phares chrome en signature. Molleton dense, col côtelé, coupe droite : le confort road-trip sans…','apparel',52.90,'EUR','stripe','GETAWAY SEASON',0,142,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='cassette-coast-crewneck');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Coque Sunset Stripe','sunset-stripe-case','Le dernier rayon avant la nuit, dans ta poche. Cette coque tough à impression all-over porte le motif Sunset Stripe de la collection GETAWAY SEASON de ViceHub X : dégradé de coucher de soleil néon, rose, cyan, violet et orange fondus sur le noir. Double couche antichoc, bords surélevés, découpes précises : la protection qui encaisse la cavale sans trahir le style. Impression à la demande…','accessory',26.90,'EUR','stripe','GETAWAY SEASON',0,143,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='sunset-stripe-case');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Casquette Trucker Outrun','outrun-trucker-cap','Casquette relevée, phares allumés. Cette trucker mesh noire porte une broderie à plat Outrun de la collection GETAWAY SEASON de ViceHub X — la grille néon en perspective de la cavale. Façade structurée, mesh respirant à l''arrière, snap réglable : le couvre-chef road-trip qui respire sur l''autoroute comme en ville. Broderie rose et cyan qui claque sur le noir, accent chrome des phares…','apparel',28.90,'EUR','stripe','GETAWAY SEASON',0,144,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='outrun-trucker-cap');
