INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Mug Sunset Stripe','sunset-stripe-mug','Le coucher de soleil dans ta tasse, chaque matin. Ce mug céramique 11oz à impression wrap all-over déploie le motif Sunset Stripe de la collection GETAWAY SEASON de ViceHub X : dégradé néon rose, cyan, violet et orange fondu sur le noir, phares chrome en signature. Céramique robuste, prise en main agréable, impression enveloppante à 360°. Imprimé à la demande pour des couleurs franches qui…','accessory',17.90,'EUR','stripe','GETAWAY SEASON',0,146,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='sunset-stripe-mug');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Poster Chrome Boulevard A2','chrome-boulevard-poster-a2','Accroche la cavale au mur. Ce poster A2 à impression mate déploie le Chrome Boulevard néon de la collection GETAWAY SEASON de ViceHub X : la grille outrun en perspective, rose, cyan, violet et orange qui ruissellent sur le bitume mouillé du noir profond, phares chrome en signature. Papier mat de qualité, rendu sans reflet, couleurs profondes prêtes à encadrer. Imprimé à la demande pour un tirage…','poster',26.90,'EUR','stripe','GETAWAY SEASON',0,147,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='chrome-boulevard-poster-a2');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Tapis de Bureau Outrun Highway','outrun-highway-desk-mat','Déploie l''autoroute néon sur ton setup. Ce tapis de bureau XL ViceHub X étire la grille outrun en perspective, phares chrome et bitume mouillé réfléchissant, du clavier jusqu''aux bords cousus qui ne s''effilochent pas. Issu de la collection GETAWAY SEASON, il capture cette fenêtre électrique entre le dernier coup et la route ouverte, dans une palette rose, cyan, violet et orange posée sur noir…','accessory',24.90,'EUR','stripe','GETAWAY SEASON',0,148,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='outrun-highway-desk-mat');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Tee Flamingo Noir','flamingo-noir-tee','Le flamant réinventé version nuit. Ce tee ViceHub X en coton 180g noir pose un flamant néon isolé sur le devant et une skyline de bord de mer imprimée au dos, beaucoup de noir négatif autour pour un rendu tonal, clean et portable au quotidien. Signature de la collection NEON NOIR, un seul pop néon rose, cyan ou violet qui claque sans crier. Impression à la demande DTG, couleurs profondes, coupe…','apparel',32.90,'EUR','stripe','NEON NOIR',0,149,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='flamingo-noir-tee');
