INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Sweat Col Rond Midnight','midnight-crewneck','Le sweat de minuit, sobre et solide. Ce col rond ViceHub X en molleton heavyweight noir place un visuel skyline de bord de mer sur le devant et la composition Bay At Midnight au dos, un seul néon posé sur beaucoup de noir négatif, signature NEON NOIR tonale et discrète. Impression à la demande DTG, maille dense, côtes fermes aux poignets et à l''encolure, tombé net qui vieillit bien. Produit…','apparel',49.90,'EUR','stripe','NEON NOIR',0,152,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='midnight-crewneck');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Debardeur Flamingo Noir','flamingo-noir-tank','Le flamant, version sans manches pour les nuits chaudes. Ce débardeur ViceHub X en coton noir isole un flamant néon sur le devant, cerné de noir négatif pour un rendu tonal, clean et facile à porter. Pur esprit NEON NOIR : un seul pop rose, cyan ou violet qui claque sur le noir profond, sans surenchère. Impression à la demande DTG, maille respirante, emmanchures nettes, coupe près du corps…','apparel',27.90,'EUR','stripe','NEON NOIR',0,153,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='flamingo-noir-tank');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Coque Miami Skyline','miami-skyline-case','Ta ville en néon, au creux de la main. Cette coque tough ViceHub X habille ton téléphone d''un visuel skyline de Miami à minuit, gratte-ciel et palmiers chrome imprimés all-over sur noir profond, avec ce seul pop néon signature NEON NOIR. Disponible sur de nombreux modèles, structure double couche qui absorbe les chocs, découpes précises, boutons réactifs. Impression à la demande, chaque coque…','accessory',26.90,'EUR','stripe','NEON NOIR',0,154,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='miami-skyline-case');
INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Bonnet Brode Flamingo','flamingo-embroidered-beanie','Le flamant, brodé fil à fil. Ce bonnet à revers ViceHub X en maille noire arbore un flamant néon en broderie à plat, un seul motif net posé sur le noir, pure logique NEON NOIR tonale et minimaliste. Broderie durable qui ne se fissure pas, maille douce et chaude, revers ajustable qui va à tout le monde. Produit à la demande, jamais surstocké. Un accessoire clean et mixte qui porte l''esprit Miami…','apparel',26.90,'EUR','stripe','NEON NOIR',0,155,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='flamingo-embroidered-beanie');
