INSERT INTO products (name, slug, description, category, price, currency, sale_type, badge, active, sort, lang) SELECT 'Tote Monogramme VHX','vhx-monogram-tote','Le monogramme maison, à porter partout. Ce tote bag ViceHub X en coton noir affiche le motif VHX en néon tonal sur le noir, un seul pop signature NEON NOIR, minimal et immédiatement reconnaissable pour les initiés. Grand volume, anses solides, toile robuste qui encaisse le quotidien, courses, cours ou virées nocturnes. Impression ou broderie à la demande, chaque sac est produit après ta…','accessory',24.90,'EUR','stripe','NEON NOIR',0,157,'fr' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM products WHERE slug='vhx-monogram-tote');
